class Solution {
public:
    int maxArea(vector<int>& height) {
        int l = 0;
        int r = static_cast<int>(height.size()) - 1;
        int maxArea = 0;
        while (l < r) {
            int h = height[l] < height[r] ? height[l] : height[r];
            int cur = (r - l) * h;
            if (cur > maxArea) maxArea = cur;
            if (height[l] < height[r])
                ++l;
            else
                --r;
        }
        return maxArea;
    }
};
